Translate("deDE", "moonglade", {
	title = "Moonglade",
	aliases = { "die Lichtung" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Moonglade ist ein verborgenes Tal in den Bergen des nördlichen {link:kalimdor}Kalimdor{/link}, zwischen {link:felwood}Teufelswald{/link} und {link:winterspring}Winterspring{/link}. In seiner Mitte liegt ein stiller See, umringt von silbernem Gras und uralten Bäumen, und an seinen Ufern steht das Dorf {link:nighthaven}Nighthaven{/link}. Dies ist der heilige Boden des {link:cenarion-circle}Zirkels des Cenarius{/link}, des Ordens der Druiden, und der Sitz von {link:keeper-remulos}Bewahrer Remulos{/link}, dem Sohn des {link:cenarius}Cenarius{/link}. Keine Armee hält es besetzt. {link:night-elves}Nachtelf{/link} und {link:tauren}Tauren{/link} gehen seine Pfade als Freunde, und seine Hüter dulden innerhalb seiner Grenzen keine Gewalt.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet das Jahr, in dem die Druiden Moonglade zum ersten Mal zu ihrer Zuflucht machten. Seine Namen verraten etwas über seine Vergangenheit. Der See trägt den Namen Elunes, der Mondgöttin der {link:night-elves}Nachtelfen{/link}. Die Grabhügel im Osten tragen den Namen von {link:malfurion-stormrage}Malfurion Stormrage{/link}, dem ersten Druiden, dessen Anhänger lernten, lange Zeitalter hindurch im {link:emerald-dream}Smaragdgrünen Traum{/link} zu schlafen. Die Druiden sagen, dass jene, die in Moonglade ruhen, unter der Wacht des Bewahrers schlafen. Es war nie eine Stadt oder eine Festung, nur ein Ort der Lehre und der Ruhe.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Die Lichtung ist in Frieden, doch der Zirkel, der in ihr wohnt, ist es nicht. {link:malfurion-stormrage}Malfurion{/link} schläft und ist nicht zurückgekehrt. In {link:darnassus}Darnassus{/link} führt Erzdruide {link:fandral-staghelm}Fandral Staghelm{/link} die Druiden der {link:night-elves}Nachtelfen{/link}, und er und {link:keeper-remulos}Bewahrer Remulos{/link} haben begonnen, einander zu misstrauen. Jeder verdächtigt den anderen der Täuschung, während die seltsame Verderbnis von {link:teldrassil}Teldrassil{/link} ungeheilt fortschreitet. Moonglade hat sich stattdessen nach außen gewandt. Seine Druiden haben die {link:tauren}Tauren{/link} willkommen geheißen und durch sie die {link:horde}Horde{/link}. Seine Gesandten suchen Hilfe bei jedem Volk, das sie geben will: gegen Gift in der {link:darkshore}Dunkelküste{/link}, gegen die Teufelsranke von Eldre'Thalas und gegen ein uraltes Übel, das sich in {link:silithus}Silithus{/link} regt. Seit Kurzem sind Druiden der {link:skyborne}Shen'dorei{/link} von einer fernen Insel im Himmel nach {link:nighthaven}Nighthaven{/link} gekommen, und ein Geist ihrer Heimat ist gekommen, sie zu empfangen.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die Druiden des Zirkels des {link:cenarius}Cenarius{/link}.{/b} {link:night-elves}Nachtelfen{/link} und {link:tauren}Tauren{/link}, die auf der Lichtung lehren, studieren und schlafen, geführt von {link:keeper-remulos}Bewahrer Remulos{/link} und seinem Haushofmeister {link:rabine-saturna}Rabine Saturna{/link}.
• {b}Die Hüter von Moonglade.{/b} {link:sentinels}Schildwachen{/link} des Zirkels, die den Frieden der Lichtung wahren und ihren Schrein bewachen.
• {b}Die großen Geister.{/b} Uralte Geister der Wildnis, die jungen Druiden die Gestalten ihrer Art lehren.
• {b}Die ruhelosen Toten.{/b} In den Stormrage Grabhügeln wandeln die Geister gefallener Druiden der Klaue voller Zorn umher.
• {b}Die {link:timbermaw-furbolgs}Holzschlund{/link}.{/b} Die {link:furbolgs}Furbolgs{/link} der {link:timbermaw-hold}Holzschlundfeste{/link} bewachen die Tunnel, die der einzige Weg in die Lichtung sind, und sie heißen nicht jeden Reisenden willkommen.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Das Zeitalter der Ahnen.{/b} Die Druiden lernten ihre Kunst im {link:war-of-the-ancients}Krieg der Ahnen{/link} von {link:cenarius}Cenarius{/link} und bewahrten sie zehntausend Jahre lang, die meisten davon im Schlaf.
• {b}Der Dritte Krieg.{/b} Als die {link:burning-legion}Brennende Legion{/link} zurückkehrte, erwachten die Druiden, um zu kämpfen. Cenarius fiel im {link:ashenvale}Eschental{/link}, und in der {link:battle-of-mount-hyjal}Schlacht um den Berg Hyjal{/link} gab {link:nordrassil}Nordrassil{/link} seine Kraft, um {link:archimonde}Archimonde{/link} zu vernichten.
• {b}Der offene Zirkel.{/b} Nach dem Krieg nahm der Zirkel Druiden der {link:tauren}Tauren{/link} auf, als ersten unter ihnen {link:hamuul-runetotem}Hamuul Runetotem{/link}. Moonglade wurde zum gemeinsamen Boden beider Völker.]=],
		},
		{
			title = "Legenden der Lichtung",
			text = [=[• Die Druiden erzählen von Omen, einem großen Wolf aus dem {link:war-of-the-ancients}Krieg der Ahnen{/link}, den dämonische Magie gegen seine Verbündeten wandte. In Moonglade niedergestreckt, schläft er im {link:lake-elune-ara}Elune'ara{/link} See und regt sich einmal im Jahr, zum Mondfest.
• Südlich der Lichtung, jenseits von {link:felwood}Teufelswald{/link} und {link:winterspring}Winterspring{/link}, erheben sich die Höhen des {link:mount-hyjal}Bergs Hyjal{/link}, wo {link:nordrassil}Nordrassil{/link} noch immer steht. Auch unter diesem Berg reichen die Grabhügel der Druiden der Klaue tief hinab, und die tiefsten von ihnen heißen {link:the-barrow-deeps}The Barrow Deeps{/link}.
• {link:umber}Umber{/link}, der Archivar von {link:nighthaven}Nighthaven{/link}, warnt jeden Besucher, {link:rabine-saturna}Rabine Saturna{/link} niemals warten zu lassen. Wer es doch tut, sagt er, findet sich womöglich mit Honig übergossen wieder.]=],
		},
	},
})

Translate("deDE", "nighthaven", {
	title = "Nighthaven",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Nighthaven ist das einzige Dorf von {link:moonglade}Moonglade{/link}, erbaut an den Ufern des {link:lake-elune-ara}Elune'ara{/link} Sees. Seine Häuser sind im alten Stil der {link:night-elves}Nachtelfen{/link} errichtet, und neben ihnen stehen die Zelte der Taurendruiden, die sich dem Zirkel angeschlossen haben. {link:rabine-saturna}Rabine Saturna{/link} führt die Angelegenheiten des Dorfes für {link:keeper-remulos}Bewahrer Remulos{/link}. {link:dendrite-starblaze}Dendrite Starblaze{/link} und {link:loganaar}Loganaar{/link} unterrichten die jungen Druiden, die hierher kommen, und der Archivar {link:umber}Umber{/link} wandert zwischen seinen Regalen umher. Reiter des Zirkels tragen Druiden nach {link:darnassus}Darnassus{/link} und nach {link:thunder-bluff}Thunder Bluff{/link}, während Hippogryphen und Windreiter an den Rändern der Lichtung warten. Nighthaven ist abgelegen und bleibt für sich. Nur zum Mondfest öffnet es seine Arme allen Völkern der Welt.]=],
		},
	},
})

Translate("deDE", "shrine-of-remulos", {
	title = "Der Schrein von Remulos",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Schrein von Remulos steht im Nordwesten von {link:moonglade}Moonglade{/link}, zwischen alten Bäumen am Rand des Sees. Hier hält der Bewahrer selbst am häufigsten Wacht. Der Schrein ist eine Würdigung des Werkes des Zirkels des {link:cenarius}Cenarius{/link}, der Bewahrung der Natur und des Gleichgewichts, und die Hüterin {link:tajarri}Tajarri{/link} dient ihm. Junge Druiden, die die Prüfung des Sees bestehen, bringen ein Kleinod aus den Wassern darunter und legen es als Zeichen der Achtung am Schrein nieder. Nicht weit im Norden hat der Große Bärengeist sein Zuhause.]=],
		},
	},
})

Translate("deDE", "lake-elune-ara", {
	title = "Der Elune'ara See",
	aliases = { "Elune'ara" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Elune'ara See füllt das Herz von {link:moonglade}Moonglade{/link}. Er trägt den Namen Elunes, und seine klaren, tiefen Wasser spiegeln den Mond über der Lichtung. {link:nighthaven}Nighthaven{/link} steht an seinen Ufern, und Brücken überspannen ihn, wo das Land schmaler wird. Der See ist Teil der Lehre des Zirkels. Junge Druiden tauchen in seine Tiefen auf der Suche nach Kleinoden des Schreins, die schnell verblassen, sobald man sie an die Luft bringt. Der See hütet auch ein älteres Geheimnis. Es heißt, dass der gefallene Wolf Omen in seinem Schlamm schläft, von Elune gesegnet und unfähig zu sterben.]=],
		},
	},
})

Translate("deDE", "stormrage-barrow-dens", {
	title = "Die Stormrage Grabhügel",
	aliases = { "Stormrage Grabhügel" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Stormrage Grabhügel liegen im Südosten von {link:moonglade}Moonglade{/link}, hinter einem großen Tor im Hang. Sie tragen den Namen von {link:malfurion-stormrage}Malfurion Stormrage{/link}, und sie sind die Ruhestätte von Druiden. Nicht alle, die dort liegen, ruhen in Frieden. Zornige Geister der Druiden der Klaue wandeln durch die Hallen und fallen über jeden her, der eintritt. Der Große Katzengeist, der in der Nähe wohnt, bewahrt drei Relikte seiner Gunst in den Grabhügeln. Eine Statue am Eingang leiht jenen einen Mantel aus Schatten, die an den Geistern vorbeischleichen müssen, um sie zu holen.]=],
		},
	},
})

Translate("deDE", "keeper-remulos", {
	title = "Bewahrer Remulos",
	subtitle = "Hüter von Moonglade",
	found = "Der Schrein von Remulos, nordwestlich von Nighthaven",
	hint = [=[Sucht den Sohn des Cenarius an dem Schrein, der seinen Namen trägt.]=],
	allegiance = "Zirkel des Cenarius",
	aliases = { "Remulos" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Bewahrer Remulos ist ein Sohn des Halbgottes {link:cenarius}Cenarius{/link} und der Hüter von {link:moonglade}Moonglade{/link}. Wie sein Vater ist er ein Wesen der Wildnis, ebenso sehr Wald wie Fleisch. Er wacht über die heilige Lichtung und über die Druiden, die in ihr schlafen, und er leitet den {link:cenarion-circle}Zirkel des Cenarius{/link} in seinem Werk: der Bewahrung der Natur und des Gleichgewichts.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Da {link:malfurion-stormrage}Malfurion Stormrage{/link} im {link:emerald-dream}Smaragdgrünen Traum{/link} verloren ist, haben die Druiden zwei Mittelpunkte und zwei Anführer. In {link:darnassus}Darnassus{/link} herrscht Erzdruide {link:fandral-staghelm}Fandral Staghelm{/link} aus den Ästen des neuen Weltenbaums. In {link:moonglade}Moonglade{/link} hütet Remulos den älteren Boden. Die beiden vertrauen einander nicht mehr. Remulos hat entschieden, die Lichtung allen zu öffnen, die der lebendigen Welt dienen, {link:tauren}Tauren{/link} und {link:night-elves}Nachtelfen{/link}, {link:horde}Horde{/link} und {link:alliance}Allianz{/link} gleichermaßen. Aus seiner Lichtung, nicht aus der Stadt des Erzdruiden, ruft der Zirkel nun sterbliche Streiter gegen die Gefahren {link:kalimdor}Kalimdors{/link}.]=],
		},
		{
			title = "Ein Sohn des Cenarius",
			text = [=[Die Bewahrer des Hains sind die Söhne des {link:cenarius}Cenarius{/link}, und Remulos ist einer von ihnen. Sein Bruder Zaetar war der erste Sohn. Vor langer Zeit suchte Zaetar Prinzessin Theradras auf, eine große Macht der elementaren Erde, und sie gebar ihm die ersten {link:centaurs}Zentauren{/link}. Seine eigenen Kinder wandten sich gegen ihn und töteten ihn, und Theradras nahm seine Überreste in die Höhlen von {red:maraudon}Maraudon{/red}. Remulos glaubte seinen Bruder für immer an Hochmut und Zorn verloren. Dann, im {link:third-war}Dritten Krieg{/link}, fiel sein Vater im {link:ashenvale}Eschental{/link} durch die {link:orcs}Orcs{/link}. Remulos hat viel an die sterblichen Völker verloren. Die Lichtung hat er ihnen nicht verschlossen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bewacht {link:moonglade}Moonglade{/link} und die Druiden, die dort ruhen.
• Er leitet den {link:cenarion-circle}Zirkel des Cenarius{/link} vom Schrein von Remulos aus.
• Durch seinen Haushofmeister {link:rabine-saturna}Rabine Saturna{/link} ruft er die Völker der Welt auf, dem Zirkel in {link:silithus}Silithus{/link} und in den Ruinen von Eldre'Thalas beizustehen.
• Er heißt die {link:tauren}Tauren{/link}, und durch sie die {link:horde}Horde{/link}, auf der Lichtung willkommen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Wenig ist über Remulos vor dem gegenwärtigen Zeitalter geschrieben: welche Rolle er in den Kriegen der alten Welt spielte oder wann er begann, {link:moonglade}Moonglade{/link} zu hüten. Dieser Eintrag verzeichnet nur, was seine Worte und sein Amt offenbaren.]=],
		},
	},
	chapters = {
		{
			title = "Der geteilte Zirkel",
			hint = "Folgt dem Ruf des Zirkels in Moonglade.",
			text = [=[Als der Zirkel um Hilfe im fernen Westen bat, ging der Ruf durch {link:thunder-bluff}Thunder Bluff{/link} und durch {link:darnassus}Darnassus{/link}. In Thunder Bluff wurde er gern gehört. In Darnassus weigerte sich der Erzdruide, ihn selbst anzuhören. Er warnte, dass {link:moonglade}Moonglade{/link} nur Propaganda verbreite und dass er allein sein Volk aus der Dunkelheit geführt habe. Sein eigener Stellvertreter gab zu, dass der Erzdruide und der Bewahrer einander der Täuschung verdächtigten. Denen, die dennoch zur Lichtung kamen, wurde versprochen, dass sie unter Freunden stünden und dass kein Schaden aus Darnassus sie dort erreichen werde.]=],
		},
		{
			title = "Der Samen des Zaetar",
			hint = "Bringt dem Bewahrer ein Geschenk vom Geist seines Bruders.",
			text = [=[Tief in Maraudon, wo Theradras seine Überreste hütete, verweilte der Geist des Zaetar. Er wollte seine Kinder nicht verlassen, selbst nach allem, was sie getan hatten. Stattdessen sandte er den ersten Samen, der aus dem Leben gewachsen war, das seine Überreste genährt hatten, mit einer Botschaft für seinen Bruder: dass sein Geist dort fortbestehe. Als der Samen {link:moonglade}Moonglade{/link} erreichte, verstand Remulos. Sein Bruder war nicht verloren gewesen. Er hatte sich der Natur zurückgegeben, wie es seine Pflicht war, und endlich Frieden gefunden. Der Bewahrer spürte, dass der Samen eines Tages für das Volk jenes vom Krieg zerrissenen Landes von Bedeutung sein würde.]=],
		},
	},
	mentions = {
		{
			text = [=[{link:rabine-saturna}Rabine Saturna{/link}, zu seinem Haushofmeister gesandt]=],
		},
		{
			text = [=[{link:rabine-saturna}Rabine Saturna{/link}, aus {link:darnassus}Darnassus{/link} gesandt]=],
		},
		{ text = "The New Frontier" },
		{ text = "Seed of Life" },
		{ text = "Trial of the Lake, an seinem Schrein" },
	},
	bonds = {
		{ id = "cenarius", name = "Cenarius", note = "sein Vater" },
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "der erste Druide, der schläft" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "sein Rivale in Darnassus" },
		{ id = "rabine-saturna", name = "Rabine Saturna", note = "sein Haushofmeister" },
		{ id = "tajarri", name = "Tajarri", note = "Hüterin seines Schreins" },
		{ id = "keeper-marandis", name = "Bewahrer Marandis", note = "sucht die Überreste seines Bruders" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "bringt die Tauren zum Zirkel" },
	},
})

Translate("deDE", "rabine-saturna", {
	title = "Rabine Saturna",
	subtitle = "Haushofmeister von Bewahrer Remulos",
	found = "Nighthaven, am See",
	hint = "Sucht den Haushofmeister des Bewahrers im Dorf Nighthaven.",
	allegiance = "Zirkel des Cenarius",
	aliases = { "Rabine" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Rabine Saturna ist der Haushofmeister von {link:keeper-remulos}Bewahrer Remulos{/link}. Er spricht für den Bewahrer zu denen, die nach {link:moonglade}Moonglade{/link} kommen, und er begrüßt sie im Namen aller, die auf der heiligen Lichtung wohnen. Er ist geduldig und höflich, und er vergisst nie eine Schuld. Der Archivar {link:umber}Umber{/link} nennt ihn die Herbergsmutter von {link:nighthaven}Nighthaven{/link}, und nicht immer freundlich.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Rabine ist die Hand, die {link:moonglade}Moonglade{/link} der Welt entgegenstreckt. Durch ihn bittet der Zirkel Fremde aus jedem Volk, zu tun, was seine Druiden allein nicht vermögen. Er glaubt, dass die Bewahrung von {link:azeroth}Azeroth{/link} eine Sache ist, die {link:horde}Horde{/link} und {link:alliance}Allianz{/link} teilen, was auch immer ihre Streitigkeiten sind und was auch immer der Erzdruide von {link:darnassus}Darnassus{/link} sagen mag.]=],
		},
		{
			title = "Taten",
			text = [=[• Er heißt die Gesandten von {link:thunder-bluff}Thunder Bluff{/link} und {link:darnassus}Darnassus{/link} auf der Lichtung willkommen und verspricht ihnen dort Schutz.
• Er sendet Kundschafter westwärts nach {link:silithus}Silithus{/link}, wo einst ein uralter Krieg zwischen den {link:night-elves}Nachtelfen{/link} und einer fremden Macht ausgefochten wurde.
• Er sendet Sucher zu den Ruinen des Südwindpostens nach einem Reliquiar der Reinheit.
• Er sucht einen Splitter der Teufelsranke von Eldre'Thalas wegzuschließen.]=],
		},
	},
	chapters = {
		{
			title = "Das Ödland",
			hint = [=[Tragt den Brief des Haushofmeisters in die Wüste jenseits von Un'Goro.]=],
			text = [=[Westlich des {link:un-goro-crater}Un'Goro-Kraters{/link} liegt eine Wüste, an die sich wenige {link:night-elves}Nachtelfen{/link} erinnern. Vor langer Zeit bekämpfte ihr Volk dort einen schrecklichen Feind und schloss ihn weg. Rabine fürchtet, dass nun etwas daran arbeitet, ihn zu wecken. Er sandte einen Brief an {link:layo-starstrike}Layo Starstrike{/link}, den Kundschafter des Zirkels in der {link:valor-s-rest}Heldenwacht{/link}, der Begräbnisstätte der Gefallenen der Wüste. Was Layo dort fand, begann ihm recht zu geben. Mit der Zeit schickte Layo einen seltsamen, in Chitin eingeschlossenen Gegenstand heim, bestimmt für den Archivar von {link:nighthaven}Nighthaven{/link}.]=],
		},
		{
			title = "Die Teufelsranke",
			hint = [=[Bringt dem Haushofmeister einen Splitter der verderbten Ranke, sicher verschlossen.]=],
			text = [=[In den östlichen Hallen von Eldre'Thalas, in {link:feralas}Feralas{/link}, hatte ein {link:satyrs}Satyr{/link} namens Alzzin der Wildformer die Frucht der Fruchtbarkeit an sich gerissen und sie zur Teufelsranke verdorben. Kein gewöhnliches Gefäß konnte etwas so Abscheuliches fassen. Rabine erinnerte sich an ein Reliquiar der Reinheit, das vor vielen Jahren im {link:southwind-village}Südwindposten{/link} in {link:silithus}Silithus{/link} zurückgelassen worden war. Als das Reliquiar geborgen und der Splitter darin verschlossen war, nannte er den Träger einen Helden des Zirkels. Der Krieg, warnte er, sei noch lange nicht vorbei.]=],
		},
	},
	mentions = {
		{ text = "Rabine Saturna" },
		{ text = "Rabine Saturna" },
		{ text = "Wasteland" },
		{ text = "Uncovering Past Secrets" },
		{ text = "A Reliquary of Purity" },
		{ text = "Shards of the Felvine" },
	},
	bonds = {
		{ id = "keeper-remulos", name = "Bewahrer Remulos", note = "sein Herr" },
		{ id = "umber", name = "Umber", note = "der Archivar des Zirkels" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "schickt ihm die Tauren" },
		{ id = "mathrengyl-bearwalker", name = "Mathrengyl Bearwalker", note = "schickt ihm die Nachtelfen" },
	},
})

Translate("deDE", "dendrite-starblaze", {
	title = "Dendrite Starblaze",
	subtitle = "Lehrer der jungen Druiden",
	found = "Nighthaven, im Norden des Dorfes",
	hint = [=[Sucht den Druiden von Nighthaven, der die Jungen ihre ersten Gestalten lehrt.]=],
	allegiance = "Zirkel des Cenarius",
	aliases = { "Dendrite" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Dendrite Starblaze ist ein Druide des Zirkels des {link:cenarius}Cenarius{/link}, der in {link:nighthaven}Nighthaven{/link} lehrt. Fast jeder junge Druide der {link:night-elves}Nachtelfen{/link} und der {link:tauren}Tauren{/link} geht durch seine Hände. Er begrüßt jeden mit einem stillen Gebet an Vater Cenarius und einer kleinen, unsichtbaren Geste, die ihn mit Kraft erfüllt. Dann schickt er sie hinaus, um von der Wildnis selbst zu lernen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Dendrite hütet die älteste Überlieferung der Druiden: dass die Gestalten der Natur verdient und nicht einfach geschenkt werden müssen. Er schickt seine Schüler zu den großen Geistern, in den See und zu den kranken Tieren der Welt, und er beurteilt sie nach dem, was sie zurückbringen. Nun kommen auch Druiden der {link:skyborne}Shen'dorei{/link} zu ihm.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt junge Druiden zum Großen Bärengeist, um das Wesen des Bären zu erlernen.
• Er stellt die Prüfung des Sees und die Prüfung des Seelöwen jenen, die die Wassergestalt annehmen wollen.
• Er schickte junge Druiden zur {link:darkshore}Dunkelküste{/link}, als {link:auberdine}Auberdine{/link} {link:moonglade}Moonglade{/link} um Hilfe mit vergifteten Hirschen bat.
• Er schickt Schüler zum Großen Katzengeist und die Shen'dorei zu einem Geist ihrer eigenen Heimat.]=],
		},
	},
