Translate("deDE", "umber", {
	title = "Umber",
	subtitle = "Archivar des Zirkels des Cenarius",
	found = "Zwischen den Bücherregalen von Nighthaven",
	hint = [=[Sucht den Archivar, der zwischen den Regalen von Nighthaven umherwandert.]=],
	allegiance = "Zirkel des Cenarius",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Umber ist der Archivar des Zirkels des {link:cenarius}Cenarius{/link}. Er ist brillant, vergesslich und ein wenig wunderlich, und er hat Folianten gerettet, die in schlimmerem Zustand waren, als die meisten Gelehrten zu öffnen wagen würden. Er murmelt vor sich hin, während er seine Regale nach Papieren durchsucht, die er verlegt hat. Er hat das gedämpfte Gerede über Schrecken in der Wüste gehört. Insekten jeder Art mag er nicht, und er bleibt gern bei seinen Büchern.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Umber öffnete das erste Fenster in die Vergangenheit von {link:silithus}Silithus{/link}. Ein Klumpen Chitin, aus der Wüste gesandt, enthielt, wie sich zeigte, ein Tagebuch, geschrieben in einer sehr alten Form der Sprache der {link:night-elves}Nachtelfen{/link}.]=],
		},
	},
	mentions = {
		{ text = "Umber, Archivist" },
		{ text = "Uncovering Past Secrets" },
		{ text = "Under the Chitin Was..." },
	},
	bonds = {
		{ id = "rabine-saturna", name = "Rabine Saturna", note = "die Herbergsmutter, mit seinen Worten" },
	},
})

Translate("deDE", "loganaar", {
	title = "Loganaar",
	subtitle = "Druidenlehrer von Nighthaven",
	found = "Nighthaven",
	hint = [=[Sucht den Druiden, der in Nighthaven die Angehörigen des Zirkels ausbildet.]=],
	allegiance = "Zirkel des Cenarius",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Loganaar lehrt in {link:nighthaven}Nighthaven{/link} die Künste des Druiden. Anders als die Lehrer von {link:darnassus}Darnassus{/link} und {link:thunder-bluff}Thunder Bluff{/link} dient er keiner Stadt. Er bildet jeden Druiden des Zirkels aus, der auf {link:moonglade}die Lichtung{/link} kommt, {link:night-elves}Nachtelf{/link} oder {link:tauren}Tauren{/link}, und er fragt nicht nach ihren Städten oder ihren Streitigkeiten. In einem Zirkel, der zwischen Moonglade und Darnassus geteilt ist, gehören seine Lektionen allein der Lichtung.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Loganaar ist oft derjenige, der es hört, wenn jemand in der Ferne um die Hilfe eines Druiden bittet. Als ein Jäger namens {link:torwa-pathfinder}Torwa Pathfinder{/link} aus dem {link:un-goro-crater}Un'Goro-Krater{/link} Nachricht sandte, dass nur ein Druide ihm helfen könne, war es Loganaar, der die Botschaft weitergab.]=],
		},
	},
	mentions = {
		{ text = "{link:torwa-pathfinder}Torwa Pathfinder{/link}" },
	},
	bonds = {
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "lehrt im selben Dorf" },
	},
})

Translate("deDE", "tajarri", {
