			text = [=[Der Große Bärengeist wohnt im Nordwesten von {link:moonglade}Moonglade{/link}. Er ist ein weises und edles Wesen, und für alle Druiden war er der erste Lehrer im Wesen des Bären. Die Druiden von {link:darnassus}Darnassus{/link} sagen, er sei Teil der Welt, seit die Welt sich unter den Sternen dreht.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Jeder junge Druide der Klaue kommt zu Beginn des Pfades hierher. Von dem Geist tragen sie Weisheit und Kraft davon. Ihre Lehrer verlassen sich auf seine Macht, um ihrer Bestimmung Nahrung zu geben. Die Begegnung ist immer dieselbe, sagen die Druiden: ein wenig verwirrend und sehr eindringlich.]=],
		},
	},
	mentions = {
		{ text = "Great Bear Spirit" },
		{ text = "Great Bear Spirit" },
	},
	bonds = {
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "schickt ihm Schüler" },
		{ id = "urs-endris", name = "Urs'endris", note = "der Bärengeist von Zephras" },
	},
})

Translate("deDE", "great-cat-spirit", {
	title = "Großer Katzengeist",
	subtitle = "Lehrer des stillen Schattens",
	found = "Der Süden von Moonglade, westlich der Stormrage Grabhügel",
	hint = [=[Sucht den Geist der Katze nahe den Grabhügeln im Süden der Lichtung.]=],
	allegiance = "Die Geister der Wildnis · Zirkel des Cenarius",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Große Katzengeist wohnt im Süden von {link:moonglade}Moonglade{/link}, nahe den Stormrage Grabhügeln. Er lehrt junge Druiden das Wesen der Katze: List, Heimlichkeit und Wildheit, wenn kein Weg zur Flucht mehr bleibt. Worte allein stellen ihn nicht zufrieden. Wer zu ihm kommt, muss zeigen, was er ist, nicht es sagen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Wer seine Gestalt annehmen will, muss zuerst drei Relikte seiner Gunst aus den Grabhügeln bergen, vorbei an den zornigen Geistern der Druiden der Klaue. Eine Statue am Eingang der Grabhügel verleiht ihnen Heimlichkeit. Erst wenn alle drei Relikte zurückgebracht sind, gibt er seinen Segen und wünscht seinen Schülern Schatten, die sie verbergen, und Beute, die ihren Klauen leicht erliegt.]=],
		},
	},
	mentions = {
		{ text = "The Great Cat Spirit" },
		{ text = "Blessings of the Great Cat Spirit" },
	},
	bonds = {
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "schickt ihm Schüler" },
		{ id = "avatar-of-saeyleenan", name = "Avatar von Saeyleenan", note = "ein Katzengeist von Zephras" },
	},
})

Translate("deDE", "avatar-of-saeyleenan", {
	title = "Avatar von Saeyleenan",
	subtitle = "Der Große windgetragene Katzengeist",
	found = "Der Süden von Moonglade, südlich der Zwillingsbrücken",
