	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Avatar von Saeyleenan ist ein windgetragener Katzengeist von {link:zephras-isle}Zephras Isle{/link}, der Heimat der {link:skyborne}Shen'dorei{/link}. Er ist seit Kurzem in {link:moonglade}Moonglade{/link} erschienen und hat die Druiden von {link:nighthaven}Nighthaven{/link} gebeten, ihm die jungen Druiden seines Volkes zu schicken. Er lehrt sie die Katzengestalt von Zephras, die sich ein wenig von der auf {link:azeroth}Azeroth{/link} bekannten Gestalt unterscheidet.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Der Avatar ist ein Zeichen, dass die Geister von {link:zephras-isle}Zephras{/link} ihre Kinder nicht vergessen haben. Er stellt ihnen dieselbe Prüfung wie der Große Katzengeist, in den Grabhügeln östlich seines Ortes. Denen, die bestehen, gibt er seinen Segen und den Wunsch, dass die Winde ihre Schritte leiten mögen. Viel mehr habe er sie hier nicht zu lehren, sagt er, und er hoffe, sie auf Zephras wiederzusehen.]=],
		},
	},
	mentions = {
		{ text = "The Great Windborne Cat Spirit" },
		{ text = "The Great Windborne Cat Spirit" },
		{ text = "Blessings of the Great Windborne Cat Spirit" },
	},
	bonds = {
		{ id = "great-cat-spirit", name = "Großer Katzengeist", note = "sein Gegenstück auf der Lichtung" },
		{ id = "urs-endris", name = "Urs'endris", note = "ein großer Geist derselben Insel" },
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "führt seine Schüler" },
	},
})
